const normalizePathname = (pathname: string) => {
  const normalized = pathname.replace(/\/+$/, '') || '/';
  return normalized === '' ? '/' : normalized;
};

const getFallbackCachedThreads = (storageKey: string) => {
  if (typeof window === 'undefined') return null;
  for (let index = 0; index < window.localStorage.length; index += 1) {
    const key = window.localStorage.key(index);
    if (!key || !key.startsWith(`${storageKey}:`)) continue;
    const rawValue = window.localStorage.getItem(key);
    if (!rawValue) continue;

    try {
      const parsed = JSON.parse(rawValue);
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed;
      }
    } catch {
      continue;
    }
  }
  return null;
};

const getFallbackCachedMessages = (threadId: string) => {
  if (typeof window === 'undefined') return null;
  const suffix = `:${threadId}`;
  for (let index = 0; index < window.localStorage.length; index += 1) {
    const key = window.localStorage.key(index);
    if (!key || !key.startsWith(`${CHAT_MESSAGES_STORAGE_KEY}:`) || !key.endsWith(suffix)) continue;
    const rawValue = window.localStorage.getItem(key);
    if (!rawValue) continue;
    try {
      const parsed = JSON.parse(rawValue);
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed;
      }
    } catch {
      continue;
    }
  }
  return null;
};

const getOAuthRedirectUrl = () => {
  if (Capacitor.isNativePlatform()) return NATIVE_OAUTH_REDIRECT_URL;
  const currentOrigin = typeof window !== 'undefined' ? window.location.origin : '';
  const currentPath = typeof window !== 'undefined' ? normalizePathname(window.location.pathname) : APP_PUBLIC_PATH;
  const fallbackCurrentUrl = `${currentOrigin}${currentPath === '/' ? APP_PUBLIC_PATH : currentPath}`;

  if (CONFIGURED_OAUTH_REDIRECT_URL) {
    try {
      const configuredUrl = new URL(CONFIGURED_OAUTH_REDIRECT_URL);
      const configuredPath = normalizePathname(configuredUrl.pathname);
      const isKnownPortalPath = currentPath === APP_PUBLIC_PATH || currentPath === ADMIN_PORTAL_PATH;
      const isLocalHost = /^(localhost|127\.0\.0\.1)$/i.test(window.location.hostname);
      const configuredMatchesCurrentOrigin = configuredUrl.origin === currentOrigin;

      // En desarrollo priorizamos el host/puerto actual para evitar cortes de OAuth
      // cuando VITE_AUTH_REDIRECT_URL quedó apuntando a otro puerto.
      if (isLocalHost && !configuredMatchesCurrentOrigin) {
        return fallbackCurrentUrl;
      }

      if (isKnownPortalPath && configuredPath !== currentPath) {
        return `${currentOrigin}${currentPath}`;
      }
      return CONFIGURED_OAUTH_REDIRECT_URL;
    } catch {
      return fallbackCurrentUrl || CONFIGURED_OAUTH_REDIRECT_URL;
    }
  }
  return fallbackCurrentUrl || `${currentOrigin}${APP_PUBLIC_PATH}`;
};

const getReadableOAuthError = (rawError: string | null, lang: 'es' | 'en') => {
  if (!rawError) return null;
  const decoded = decodeURIComponent(rawError.replace(/\+/g, ' '));
  if (/redirect_to|redirect url|redirect url is not allowed|not allowed/i.test(decoded)) {
    return lang === 'es'
      ? 'El dominio actual no está autorizado en Supabase Auth. Agregá esta URL pública a Redirect URLs o definí VITE_AUTH_REDIRECT_URL.'
      : 'This domain is not authorized in Supabase Auth. Add this public URL to Redirect URLs or set VITE_AUTH_REDIRECT_URL.';
  }
  return decoded;
};

const toDateInputValue = (date: Date) => {
  const year = date.getFullYear();
  const month = `${date.getMonth() + 1}`.padStart(2, '0');
  const day = `${date.getDate()}`.padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const getTodayDateInputValue = () => {
  const date = new Date();
  date.setHours(0, 0, 0, 0);
  return toDateInputValue(date);
};

const addDaysToDateInputValue = (value: string, days: number) => {
  if (!value) return '';
  const [year, month, day] = value.split('-').map(Number);
  if (!year || !month || !day) return '';
  const date = new Date(year, month - 1, day);
  date.setDate(date.getDate() + days);
  return toDateInputValue(date);
};

const sanitizePersonNameInput = (value: string) =>
  value
    .replace(/[^A-Za-zÁÉÍÓÚáéíóúÑñ'’ -]/g, '')
    .replace(/\s{2,}/g, ' ')
    .replace(/^\s+/, '');

const sanitizePhoneInput = (value: string) =>
  value
    .replace(/[^+\d\s-()]/g, '')
    .replace(/\s{2,}/g, ' ')
    .replace(/^\s+/, '');

const isPlaceholderAvatar = (value?: string | null) =>
  !value || value === DEFAULT_PROFILE_AVATAR || value.includes('i.pravatar.cc/');

const isPersistedMediaUrl = (value?: string | null) =>
  Boolean(value && /^https?:\/\//i.test(value) && !/^https?:\/\/localhost[:/]/i.test(value));

const filterPersistedMediaUrls = (values: Array<string | null | undefined>) =>
  values.filter((value): value is string => isPersistedMediaUrl(value));

const pickBestAvatar = (...candidates: Array<string | null | undefined>) =>
  candidates.find((candidate) => candidate && isPersistedMediaUrl(candidate) && !isPlaceholderAvatar(candidate))
  || candidates.find((candidate) => candidate && /^https?:\/\//i.test(candidate) && !isPlaceholderAvatar(candidate))
  || DEFAULT_PROFILE_AVATAR;

const formatDisplayDate = (value?: string) => {
  if (!value) return '-';
  const date = new Date(`${value}T00:00:00`);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

const formatDisplayDateDashed = (value?: string) =>
  formatDisplayDate(value).replace(/\//g, '-');

const formatReviewDate = (value?: string) => {
  if (!value) return '-';
  const trimmed = value.trim();
  if (!trimmed) return '-';
  if (/^\d{2}[/-]\d{2}[/-]\d{4}$/.test(trimmed)) {
    return trimmed.replace(/\//g, '-');
  }
  const parsed = new Date(trimmed);
  if (Number.isNaN(parsed.getTime())) return trimmed;
  return parsed.toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit', year: 'numeric' }).replace(/\//g, '-');
};

const getReadableErrorMessage = (error: unknown) => {
  if (error instanceof Error) return error.message;
  if (error && typeof error === 'object') {
    const candidate = error as Record<string, unknown>;
    return [
      typeof candidate.message === 'string' ? candidate.message : '',
      typeof candidate.details === 'string' ? candidate.details : '',
      typeof candidate.hint === 'string' ? candidate.hint : '',
      typeof candidate.code === 'string' ? candidate.code : '',
    ].filter(Boolean).join(' | ');
  }
  return String(error || '');
};

