type GeoRefSuggestion = {
  id: string;
  label: string;
};

const fetchGeoRefSuggestions = async (query: string, signal?: AbortSignal): Promise<GeoRefSuggestion[]> => {
  const trimmedQuery = query.trim();
  if (trimmedQuery.length < 2) return [];

  const [localitiesRes, provincesRes] = await Promise.all([
    fetch(
      `https://apis.datos.gob.ar/georef/api/localidades?nombre=${encodeURIComponent(trimmedQuery)}&campos=nombre,provincia&max=8`,
      { signal }
    ),
    fetch(
      `https://apis.datos.gob.ar/georef/api/provincias?nombre=${encodeURIComponent(trimmedQuery)}&campos=nombre&max=5`,
      { signal }
    ),
  ]);

  const [localitiesData, provincesData] = await Promise.all([
    localitiesRes.ok ? localitiesRes.json() : Promise.resolve({ localidades: [] }),
    provincesRes.ok ? provincesRes.json() : Promise.resolve({ provincias: [] }),
  ]);

  const localitySuggestions = Array.isArray(localitiesData.localidades)
    ? localitiesData.localidades.map((item: any) => ({
        id: `locality-${item.nombre}-${item.provincia?.nombre || 'argentina'}`,
        label: [item.nombre, item.provincia?.nombre, 'Argentina'].filter(Boolean).join(', '),
      }))
    : [];

  const provinceSuggestions = Array.isArray(provincesData.provincias)
    ? provincesData.provincias.map((item: any) => ({
        id: `province-${item.nombre}`,
        label: [item.nombre, 'Argentina'].filter(Boolean).join(', '),
      }))
    : [];

  return Array.from(
    new Map(
      [...localitySuggestions, ...provinceSuggestions]
        .filter((item) => item.label)
        .map((item) => [item.label.toLowerCase(), item])
    ).values()
  ).slice(0, 8);
};

const buildNominatimLabel = (item: any) => {
  const address = item?.address || {};
  const locality = address.city || address.town || address.village || address.municipality || address.hamlet || address.county || '';
  const state = address.state || address.region || '';
  const country = address.country || '';
  const label = [locality, state, country].filter(Boolean).join(', ');
  return label || item?.display_name || '';
};

const fetchGlobalLocationSuggestions = async (query: string, signal?: AbortSignal): Promise<GeoRefSuggestion[]> => {
  const trimmedQuery = query.trim();
  if (trimmedQuery.length < 2) return [];

  const response = await fetch(
    `https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=8&q=${encodeURIComponent(trimmedQuery)}`,
    {
      signal,
      headers: {
        'Accept-Language': 'es',
      },
    }
  );

  if (!response.ok) {
    throw new Error('Failed to load global locations');
  }

  const data = await response.json();
  if (!Array.isArray(data)) return [];

  return data
    .map((item: any, index: number) => {
      const label = buildNominatimLabel(item);
      return {
        id: `global-${item.place_id || index}`,
        label,
      };
    })
    .filter((item: GeoRefSuggestion) => item.label);
};

const fetchLocationSuggestions = async (query: string, signal?: AbortSignal): Promise<GeoRefSuggestion[]> => {
  const [geoRefSuggestions, globalSuggestions] = await Promise.allSettled([
    fetchGeoRefSuggestions(query, signal),
    fetchGlobalLocationSuggestions(query, signal),
  ]);

  const merged = [
    ...(geoRefSuggestions.status === 'fulfilled' ? geoRefSuggestions.value : []),
    ...(globalSuggestions.status === 'fulfilled' ? globalSuggestions.value : []),
  ];

  return Array.from(
    new Map(merged.map((item) => [item.label.toLowerCase(), item])).values()
  ).slice(0, 8);
};

const getOAuthIdentityData = (sessionUser: any) => {
  if (!Array.isArray(sessionUser?.identities)) return {};
  const activeProvider = sessionUser?.app_metadata?.provider;
  const matchedIdentity = activeProvider
    ? sessionUser.identities.find((identity: any) => identity?.provider === activeProvider && identity?.identity_data)
    : null;
  const fallbackIdentity = sessionUser.identities.find((identity: any) => identity?.identity_data);
  return matchedIdentity?.identity_data || fallbackIdentity?.identity_data || {};
};

const getOAuthUserName = (sessionUser: any) => {
  const identityData = getOAuthIdentityData(sessionUser);
  return (
    sessionUser?.user_metadata?.full_name ||
    sessionUser?.user_metadata?.name ||
    sessionUser?.user_metadata?.user_name ||
    identityData?.full_name ||
    identityData?.name ||
    identityData?.user_name ||
    ''
  );
};

const getOAuthUserAvatar = (sessionUser: any) => {
  const identityData = getOAuthIdentityData(sessionUser);
  return (
    sessionUser?.user_metadata?.avatar_url ||
    sessionUser?.user_metadata?.picture ||
    sessionUser?.user_metadata?.photo_url ||
    sessionUser?.user_metadata?.photoURL ||
    sessionUser?.user_metadata?.avatar ||
    sessionUser?.user_metadata?.image ||
    identityData?.avatar_url ||
    identityData?.picture ||
    identityData?.photo_url ||
    identityData?.photoURL ||
    identityData?.avatar ||
    identityData?.image ||
    ''
  );
};

const getOAuthProvider = (sessionUser: any) =>
  sessionUser?.app_metadata?.provider
  || (Array.isArray(sessionUser?.identities) ? sessionUser.identities[0]?.provider : null)
  || null;

const resolveOAuthAvatar = async (session: any, sessionUser: any) => {
  const directAvatar = getOAuthUserAvatar(sessionUser);
  if (directAvatar && !isPlaceholderAvatar(directAvatar)) return directAvatar;

  const provider = getOAuthProvider(sessionUser);
  const providerToken = session?.provider_token;
  if (provider !== 'google' || !providerToken) return directAvatar;

  try {
    const response = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
      headers: {
        Authorization: `Bearer ${providerToken}`,
      },
    });
    if (!response.ok) throw new Error(`Google userinfo responded with ${response.status}`);
    const data = await response.json();
    return data?.picture || directAvatar || '';
  } catch (error) {
    console.error('Error resolving Google avatar from userinfo:', error);
    return directAvatar;
  }
};

const hydrateAuthUser = async (sessionUser: any) => {
  try {
    const { data, error } = await supabase.auth.getUser();
    if (error) throw error;
    return data.user || sessionUser;
  } catch (error) {
    console.warn('No se pudo hidratar el usuario OAuth desde auth.getUser():', error);
    return sessionUser;
  }
};

