  const sendBookingCommunicationEmail = useCallback(async (input: {
    eventKey: string;
    recipientUserId?: string;
    recipientEmail?: string;
    recipientName?: string;
    payload?: Record<string, any>;
    locale?: 'es' | 'en';
  }) => {
    const normalizedEmail = (input.recipientEmail || '').trim().toLowerCase();
    let resolvedEmail = normalizedEmail;
    let resolvedName = (input.recipientName || '').trim();
    let resolvedUserId = input.recipientUserId?.trim() || '';

    if (resolvedUserId && (!resolvedEmail || !resolvedName)) {
      try {
        const { data } = await supabase
          .from('profiles')
          .select('email, full_name')
          .or(`id.eq.${resolvedUserId},auth_user_id.eq.${resolvedUserId}`)
          .maybeSingle();
        if (data?.email && !resolvedEmail) {
          resolvedEmail = String(data.email).trim().toLowerCase();
        }
        if (data?.full_name && !resolvedName) {
          resolvedName = String(data.full_name).trim();
        }
      } catch (error) {
        console.error('Error resolving profile email for communication:', error);
      }
    }

    if (!resolvedEmail) return;

    try {
      await cumbreApi.sendCommunicationEmail({
        eventKey: input.eventKey,
        recipientEmail: resolvedEmail,
        recipientUserId: resolvedUserId || undefined,
        recipientName: resolvedName || undefined,
        locale: input.locale || regLang,
        payload: input.payload || {},
      });
    } catch (error) {
      console.error('Error sending communication email:', error);
    }
  }, [regLang]);
  const toUserHandleFromName = (name: string) => `@${(name || '').trim().toLowerCase().replace(/\s+/g, '_')}`;
  const isProfileBlocked = (id?: string, name?: string, handle?: string) => {
    const normalizedName = normalizeHandle(toUserHandleFromName(name || ''));
    const normalizedHandle = normalizeHandle(handle || '');
    return blockedProfiles.some((blocked) => {
      const blockedHandle = normalizeHandle(blocked.handle);
      if (id && blocked.id && blocked.id === id) return true;
      if (normalizedHandle && blockedHandle === normalizedHandle) return true;
      if (normalizedName && blockedHandle === normalizedName) return true;
      return false;
    });
  };
