    const containerWidth = event.currentTarget.clientWidth || window.innerWidth;
    postCarouselTouchStateRef.current[postId] = {
      startX: event.clientX,
      startY: event.clientY,
      dragging: false,
      containerWidth,
    };
    event.currentTarget.setPointerCapture?.(event.pointerId);
    setPostCarouselDragOffsetById((prev) => ({ ...prev, [postId]: 0 }));
