                      expeditionNights: '',
                      expeditionCapacity: '',
                      enrollmentStartDate: '',
                      enrollmentEndDate: '',
                      bedPrice: '',
                      currency: 'ARS',
                      coverImage: null,
                      galleryImages: [null, null, null, null],
                      expeditionVideoFile: null,
