      {selectedSpot && (
        <LocationDetails 
          spot={selectedSpot} 
          onBack={() => {
            setSelectedSpot(null);
            setEditingBookingId(null);
          }} 
          onOpenProfile={(userId) => {
            const providerPublishLabels: Record<ActivityType, string> = {
              [ActivityType.TREKKING]: regLang === 'es' ? 'Recorridos' : 'Routes',
              [ActivityType.GASTRONOMIA]: regLang === 'es' ? 'Gastronómicas' : 'Food & Drink',
              [ActivityType.ESCALADA]: regLang === 'es' ? 'Experiencias' : 'Experiences',
              [ActivityType.BOULDER]: regLang === 'es' ? 'Talleresmientos' : 'Workshopsings',
              [ActivityType.MONTANISMO]: regLang === 'es' ? 'Recorridos' : 'Routes',
              [ActivityType.SKI]: 'Ski',
              [ActivityType.RAFTING]: 'Rafting',
            };
            const organizerKey = userId || selectedSpot.organizerName || 'guide';
            const found = friends.find((f) => f.id === organizerKey || f.name === organizerKey);
            if (found && isProfileBlocked(found.id, found.name, toUserHandleFromName(found.name))) {
              return;
            }
            const organizerName = found?.name || selectedSpot.organizerName || (regLang === 'es' ? 'Guía Recorre Argentina' : 'Recorre Argentina Guide');
            const organizerSpots = spots.filter((spot) => spot.organizerUserId === organizerKey || spot.organizerName === organizerName);
            const expeditionCount = organizerSpots.filter((spot) => !!spot.activityType && expeditionActivityTypes.includes(spot.activityType)).length;
            const activityNames = Array.from(new Set(
              organizerSpots
                .map((spot) => {
                  if (spot.activityType && expeditionActivityTypes.includes(spot.activityType)) return regLang === 'es' ? 'Recorridos' : 'Routes';
                  if (spot.kind === 'event') return regLang === 'es' ? 'Eventos' : 'Events';
                  if (spot.kind === 'course') return regLang === 'es' ? 'Cursos' : 'Courses';
                  return spot.activityType || spot.placeType;
                })
                .filter(Boolean)
            ));
            const listingTypes = Array.from(new Set(
              organizerSpots
                .map((spot) => {
                  if (spot.kind === 'event') return regLang === 'es' ? 'Eventos' : 'Events';
                  if (spot.kind === 'course') return regLang === 'es' ? 'Cursos' : 'Courses';
                  if (spot.activityType) return providerPublishLabels[spot.activityType] || spot.activityType;
                  if (spot.placeType === PlaceType.REFUGIO) return regLang === 'es' ? 'Sitios' : 'Places';
                  return null;
                })
                .filter(Boolean)
            )) as string[];
            const resolvedIsProvider = !!found?.isProvider || organizerSpots.length > 0;
            setPublicProfile({
              id: organizerKey,
              chatProfileId: found?.id || (UUID_PATTERN.test(String(organizerKey || '')) ? organizerKey : undefined),
              name: organizerName,
              avatar: found?.avatar || 'https://i.pravatar.cc/150?u=guide',
              isProvider: resolvedIsProvider,
              province: organizerSpots[0]?.province || selectedSpot.province,
              expeditionsCount: expeditionCount,
              listingsCount: organizerSpots.length,
              activityLabel: activityNames.join(' · ') || (resolvedIsProvider
                ? (regLang === 'es' ? 'Prestador' : 'Provider')
                : (regLang === 'es' ? 'Viajero' : 'Traveler')),
              listingTypes,
              isFollowing: !!found?.isFollowing,
            });
            setSelectedSpot(null);
          }}
          isFavorite={favorites.has(selectedSpot.id)} 
          onToggleFavorite={toggleFavorite} 
          isForeigner={profileData.isForeigner}
          language={regLang}
          bookingUser={{ name: profileData.name, email: profileData.email }}
          bookingUsersDirectory={[
            {
              id: currentProfileId || '',
              handle: currentUserHandle.replace(/^@/, ''),
              name: profileData.name || 'Explorador',
              email: profileData.email,
            },
            ...visibleFriends.map((friend) => ({
              id: friend.id,
              handle: friend.name.toLowerCase().replace(/\s+/g, '_'),
              name: friend.name,
              email: '',
            })),
          ]}
          providerReviews={selectedSpot.placeType === PlaceType.ACTIVIDAD ? getProviderReviewsForSpot(selectedSpot) : (selectedSpot.reviews || [])}
          onAddProviderReview={(review) => addProviderReviewForSpot(selectedSpot, review)}
          onCreateAvailabilityCheck={({ spotId, dateFrom, dateTo, peopleCount }) => (
            createAvailabilityCheck({ spotId, dateFrom, dateTo, peopleCount })
          )}
          availabilityChecks={availabilityChecks.filter((check) => check.spotId === selectedSpot.id)}
          onCreateBooking={async (booking) => {
            let resolvedProviderUserId = UUID_PATTERN.test(String(booking.providerUserId || ''))
              ? String(booking.providerUserId)
              : UUID_PATTERN.test(String(selectedSpot.organizerUserId || ''))
                ? String(selectedSpot.organizerUserId)
                : '';

            if (!resolvedProviderUserId) {
              try {
                const refreshedSpot = selectedSpot.placeType === PlaceType.REFUGIO
                  ? await cumbreApi.getRefugioDetail(selectedSpot.id)
                  : await cumbreApi.getActivityDetail(selectedSpot.id);
                if (UUID_PATTERN.test(String(refreshedSpot.organizerUserId || ''))) {
                  resolvedProviderUserId = String(refreshedSpot.organizerUserId);
                }
              } catch (error) {
                console.error('Error resolving provider from listing detail before creating booking:', error);
              }
            }

            const pendingBooking: Booking = {
              ...booking,
              providerUserId: resolvedProviderUserId || booking.providerUserId,
              status: booking.status || 'pending',
              updatedAt: new Date().toISOString(),
            };
            let resolvedProfileId = currentProfileId;

            if (!resolvedProfileId) {
              try {
                const synced = await cumbreApi.ensureAuthProfile({
                  name: profileData.name,
                  email: profileData.email,
                  phone: profileData.phone,
                  instagram: profileData.instagram,
                  avatarUrl: effectiveProfileAvatar,
                  provincia: profileData.provincia,
                  birthDate: profileData.birthDate,
                  preferredSports: profileData.preferredSports,
                  providerServices: profileData.providerServices,
                  isProviderUser,
                });
                resolvedProfileId = synced.profileId;
                setCurrentProfileId(synced.profileId);
              } catch (error) {
                console.error('Error resolving explorer profile before creating booking:', error);
                if (error instanceof Error && /cuenta es administrativa|account is administrative/i.test(error.message)) {
                  await redirectPublicAdminToPortal(error.message);
                  return false;
                }
              }
            }

            if (!resolvedProfileId) {
              showToast(regLang === 'es' ? 'No se pudo vincular tu perfil para enviar la reserva.' : 'Could not resolve your profile to send the booking.');
              return false;
            }

            try {
              await cumbreApi.createBooking(resolvedProfileId, pendingBooking);
            } catch (error) {
              console.error('Error creating booking in DB:', error);
              const details = typeof error === 'object' && error !== null
                ? [
                    'message' in error ? String((error as { message?: unknown }).message || '') : '',
                    'details' in error ? String((error as { details?: unknown }).details || '') : '',
                    'hint' in error ? String((error as { hint?: unknown }).hint || '') : '',
                    'code' in error ? String((error as { code?: unknown }).code || '') : '',
                  ].filter(Boolean).join(' | ')
                : error instanceof Error
                  ? error.message
                  : '';
              showToast(regLang === 'es'
                ? `No se pudo guardar la reserva.${details ? ` ${details}` : ''}`
                : `Could not save the booking.${details ? ` ${details}` : ''}`);
              return false;
            }

            let persistedBooking = pendingBooking;
            try {
              const refreshedBooking = await cumbreApi.getBookingById(pendingBooking.id);
              if (refreshedBooking) {
                persistedBooking = refreshedBooking;
              }
            } catch (error) {
              console.error('Error refreshing booking after creation:', error);
            }

            setShelterBookings((prev) => {
              const dedup = new Map<string, Booking>();
              [persistedBooking, ...prev].forEach((booking) => {
                if (!dedup.has(booking.id)) dedup.set(booking.id, booking);
              });
              return Array.from(dedup.values());
            });
            if (pendingBooking.availabilityCheckId) {
              setAvailabilityChecks((prev) => prev.map((check) => (
                check.id === pendingBooking.availabilityCheckId
                  ? { ...check, linkedBookingId: pendingBooking.id, updatedAt: new Date().toISOString() }
                  : check
              )));
            }
            createFlowNotification(
              'provider',
              regLang === 'es' ? 'Nueva reserva pendiente' : 'New pending booking',
              regLang === 'es' ? 'Tenés una nueva reserva para revisar.' : 'You have a new booking to review.',
              persistedBooking.id
            );
            const guestHandles = Array.from(new Set(
              persistedBooking.guests
                .map((guest) => guest.appUserHandle?.trim())
                .filter((handle): handle is string => !!handle)
            )).filter((handle) => normalizeHandle(handle) !== normalizeHandle(persistedBooking.reservationUser || ''));
            if (guestHandles.length > 0) {
              createFlowNotification(
                'explorer',
                regLang === 'es' ? 'Fuiste agregado a una reserva' : 'You were added to a booking',
                regLang === 'es'
                  ? 'Te agregaron como asistente/huésped en una reserva.'
                  : 'You were added as attendee/guest to a booking.',
                persistedBooking.id,
                guestHandles
              );
            }
            return true;
          }}
          editingBooking={bookingBeingEdited}
          onUpdateBooking={(bookingId, updates) => {
            updateBookingFlow(bookingId, 'explorer_modify', { updates });
            setEditingBookingId(null);
          }}
          existingBookings={uniqueShelterBookings.filter((booking) => booking.spotId === selectedSpot.id)}
          onShowToast={(message) => showToast(message)}
        />
      )}

